def satisfies(version, rng):
    """Return True if `version` satisfies the range `rng`, else False.

    Versions are "MAJOR.MINOR.PATCH" optionally followed by "-PRERELEASE", where PRERELEASE is one or more
    dot-separated identifiers made of [0-9A-Za-z-]. MAJOR, MINOR, PATCH and purely numeric prerelease identifiers
    are non-negative integers without leading zeros ("0" is fine). Build metadata ("+...") is not allowed.
    An invalid version or range raises ValueError; the WHOLE range is validated even if an earlier part matches.

    Precedence (SemVer 2.0.0): compare MAJOR, MINOR, PATCH numerically. A version with a prerelease is lower than
    the same version without one. Prerelease identifiers are compared left to right: numeric ones numerically,
    alphanumeric ones in ASCII order, numeric always lower than alphanumeric, and if all shared identifiers are
    equal the version with fewer identifiers is lower.

    Range grammar: one or more comparator sets separated by "||" (whitespace around "||" is ignored). The range
    is satisfied if ANY set is satisfied. A set is one or more comparators separated by whitespace; it is
    satisfied if ALL its comparators are. An empty set (e.g. "1.0.0 ||") is invalid. Comparators, with no
    whitespace between operator and version:
        "V" or "=V"   equal to V
        ">V" ">=V" "<V" "<=V"
        "^V"          >=V and below the next "significant" version: < (MAJOR+1).0.0 if MAJOR > 0,
                      else < 0.(MINOR+1).0 if MINOR > 0, else < 0.0.(PATCH+1)
        "~V"          >=V and < MAJOR.(MINOR+1).0

    Prerelease rule: a version that HAS a prerelease satisfies a set only if, in addition, some comparator in that
    set names a version with the same MAJOR.MINOR.PATCH that also has a prerelease (for ^V and ~V the named
    version is V). Versions without a prerelease are not affected by this rule.
    """
    def is_ascii_digit(ch):
        return "0" <= ch <= "9"

    def is_allowed_ident_char(ch):
        return (
            is_ascii_digit(ch)
            or ("a" <= ch <= "z")
            or ("A" <= ch <= "Z")
            or ch == "-"
        )

    def parse_number(part):
        if not part:
            raise ValueError
        if not all(is_ascii_digit(ch) for ch in part):
            raise ValueError
        if len(part) > 1 and part[0] == "0":
            raise ValueError
        return int(part)

    def parse_prerelease_ident(ident):
        if not ident:
            raise ValueError
        if not all(is_allowed_ident_char(ch) for ch in ident):
            raise ValueError
        if all(is_ascii_digit(ch) for ch in ident):
            if len(ident) > 1 and ident[0] == "0":
                raise ValueError
        return ident

    def parse_version(s):
        if not isinstance(s, str):
            raise ValueError
        if "+" in s:
            raise ValueError

        dash = s.find("-")
        if dash == -1:
            base = s
            prerelease = None
        else:
            base = s[:dash]
            prerelease_str = s[dash + 1:]
            if prerelease_str == "":
                raise ValueError
            prerelease = tuple(parse_prerelease_ident(x) for x in prerelease_str.split("."))

        parts = base.split(".")
        if len(parts) != 3:
            raise ValueError

        major = parse_number(parts[0])
        minor = parse_number(parts[1])
        patch = parse_number(parts[2])

        return (major, minor, patch, prerelease)

    def parse_comparator(token):
        if not isinstance(token, str) or token == "":
            raise ValueError

        op = ""
        for candidate in (">=", "<=", "=", ">", "<", "^", "~"):
            if token.startswith(candidate):
                op = candidate
                ver_str = token[len(candidate):]
                break
        else:
            ver_str = token

        if ver_str == "":
            raise ValueError

        return op, parse_version(ver_str)

    def parse_range(r):
        if not isinstance(r, str):
            raise ValueError

        sets = []
        for part in r.split("||"):
            part = part.strip()
            if part == "":
                raise ValueError

            tokens = part.split()
            if not tokens:
                raise ValueError

            comps = []
            for token in tokens:
                comps.append(parse_comparator(token))
            sets.append(comps)

        if not sets:
            raise ValueError

        return sets

    def cmp_versions(a, b):
        for i in range(3):
            if a[i] < b[i]:
                return -1
            if a[i] > b[i]:
                return 1

        a_pre = a[3]
        b_pre = b[3]

        if a_pre is None and b_pre is None:
            return 0
        if a_pre is None:
            return 1
        if b_pre is None:
            return -1

        for x, y in zip(a_pre, b_pre):
            x_num = all(is_ascii_digit(ch) for ch in x)
            y_num = all(is_ascii_digit(ch) for ch in y)

            if x_num and y_num:
                xi = int(x)
                yi = int(y)
                if xi < yi:
                    return -1
                if xi > yi:
                    return 1
            elif x_num:
                return -1
            elif y_num:
                return 1
            else:
                if x < y:
                    return -1
                if x > y:
                    return 1

        if len(a_pre) < len(b_pre):
            return -1
        if len(a_pre) > len(b_pre):
            return 1
        return 0

    def make_upper_caret(v):
        major, minor, patch, _ = v
        if major > 0:
            return (major + 1, 0, 0, None)
        if minor > 0:
            return (0, minor + 1, 0, None)
        return (0, 0, patch + 1, None)

    def make_upper_tilde(v):
        major, minor, patch, _ = v
        return (major, minor + 1, 0, None)

    def comparator_satisfied(v, op, named):
        c = cmp_versions(v, named)

        if op == "" or op == "=":
            return c == 0
        if op == ">":
            return c > 0
        if op == ">=":
            return c >= 0
        if op == "<":
            return c < 0
        if op == "<=":
            return c <= 0
        if op == "^":
            return c >= 0 and cmp_versions(v, make_upper_caret(named)) < 0
        if op == "~":
            return c >= 0 and cmp_versions(v, make_upper_tilde(named)) < 0

        raise ValueError

    def set_satisfied(v, comps):
        if v[3] is not None:
            prerelease_allowed = False
            for _, named in comps:
                if (
                    named[3] is not None
                    and v[0] == named[0]
                    and v[1] == named[1]
                    and v[2] == named[2]
                ):
                    prerelease_allowed = True
                    break
            if not prerelease_allowed:
                return False

        for op, named in comps:
            if not comparator_satisfied(v, op, named):
                return False

        return True

    v = parse_version(version)
    sets = parse_range(rng)

    for comps in sets:
        if set_satisfied(v, comps):
            return True

    return False

