from datetime import datetime, timedelta


def next_fire(expr, after):
    """Return the first naive datetime STRICTLY after `after` (a naive datetime) that matches cron expression `expr`.
    Results always have second == 0 and microsecond == 0.

    `expr` has exactly 5 whitespace-separated fields: minute (0-59), hour (0-23), day-of-month (1-31),
    month (1-12), day-of-week (0-7, where both 0 and 7 mean Sunday, 1 = Monday ... 6 = Saturday).
    Each field is a comma-separated list of items. An item is "*" (the whole field range), "N", or "A-B" (A <= B),
    optionally followed by "/S" (S >= 1): take every S-th value of the item starting at its first value.
    "*/S" starts at the field minimum and "N/S" means N through the field maximum in steps of S.

    Day matching: a field is "unrestricted" only if it is exactly "*". If both day-of-month and day-of-week are
    restricted, a day matches when EITHER matches; otherwise both must match.

    Empty items, out-of-range values, A > B, S < 1, non-digit characters, or a wrong number of fields raise
    ValueError. If the expression has no match within 3000 days after `after` (e.g. "0 0 30 2 *"), raise ValueError.
    """
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have exactly 5 fields")

    def is_digits(s):
        return s != "" and all(c in "0123456789" for c in s)

    def parse_field(field, lo, hi):
        unrestricted = field == "*"
        values = set()

        for item in field.split(","):
            if item == "":
                raise ValueError("empty item in cron field")

            if "/" in item:
                parts = item.split("/")
                if len(parts) != 2:
                    raise ValueError("invalid cron item")
                base, step_s = parts
                if not is_digits(step_s):
                    raise ValueError("invalid step")
                step = int(step_s)
                if step < 1:
                    raise ValueError("step must be >= 1")
                has_step = True
            else:
                base = item
                step = 1
                has_step = False

            if base == "*":
                start, end = lo, hi
            elif "-" in base:
                range_parts = base.split("-")
                if len(range_parts) != 2:
                    raise ValueError("invalid range")
                a_s, b_s = range_parts
                if not is_digits(a_s) or not is_digits(b_s):
                    raise ValueError("invalid range")
                start, end = int(a_s), int(b_s)
                if start > end:
                    raise ValueError("range start must be <= end")
            else:
                if not is_digits(base):
                    raise ValueError("invalid value")
                start = int(base)
                end = hi if has_step else start

            if start < lo or end > hi:
                raise ValueError("value out of range")

            for v in range(start, end + 1, step):
                values.add(v)

        return values, unrestricted

    minute_values, _ = parse_field(fields[0], 0, 59)
    hour_values, _ = parse_field(fields[1], 0, 23)
    dom_values, dom_unrestricted = parse_field(fields[2], 1, 31)
    month_values, _ = parse_field(fields[3], 1, 12)
    dow_values, dow_unrestricted = parse_field(fields[4], 0, 7)

    dow_values = {0 if v == 7 else v for v in dow_values}

    minutes = sorted(minute_values)
    hours = sorted(hour_values)

    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = after + timedelta(days=3000)

    day = start.date()
    limit_day = limit.date()

    while day <= limit_day:
        if day.month in month_values:
            cron_dow = (day.weekday() + 1) % 7
            dom_ok = day.day in dom_values
            dow_ok = cron_dow in dow_values

            if dom_unrestricted and dow_unrestricted:
                day_ok = True
            elif dom_unrestricted:
                day_ok = dow_ok
            elif dow_unrestricted:
                day_ok = dom_ok
            else:
                day_ok = dom_ok or dow_ok

            if day_ok:
                for h in hours:
                    if day == start.date() and h < start.hour:
                        continue
                    if day == limit_day and h > limit.hour:
                        break

                    for m in minutes:
                        if day == start.date() and h == start.hour and m < start.minute:
                            continue
                        if day == limit_day and h == limit.hour and m > limit.minute:
                            break

                        candidate = datetime(day.year, day.month, day.day, h, m, 0, 0)
                        if candidate <= limit:
                            return candidate
                        break

        day += timedelta(days=1)

    raise ValueError("no matching cron time within 3000 days")

