class PatchError(ValueError):
    pass


def apply_patch(doc, ops):
    """Apply a JSON Patch (RFC 6902 subset) to `doc` and return the resulting NEW document.

    `doc` and `ops` must never be modified, and the result must share no mutable object (dict/list) with either.
    The patch is all-or-nothing: on any error, raise PatchError.

    `ops` is a list of dicts. Each has "op" (one of add, remove, replace, move, copy, test) and "path";
    add/replace/test also need "value" (which may be None); move/copy also need "from". Missing keys are errors.

    Paths are JSON Pointers: "" is the whole document; otherwise "/" followed by "/"-separated tokens in which
    "~1" stands for "/" and "~0" for "~" ("~01" is the key "~1"). A "~" not followed by 0 or 1 is an error.
    A token addressing a list must be a base-10 index without leading zeros ("0" is fine). "-" means "past the
    end of the list" and is only allowed as the final token of an add (or of the target of move/copy).

    add:     object -> set the member (replacing any existing value); list -> insert BEFORE the index
             (index == len appends, index > len is an error). Adding at "" replaces the whole document.
             The parent container must exist.
    remove:  the target must exist. Removing "" is an error.
    replace: the target must exist. Replacing "" replaces the whole document.
    move:    remove the value at "from", then add it at "path". It is an error if "path" lies strictly inside
             "from" (a proper descendant). from == path is a no-op, but "from" must still exist.
    copy:    add a deep copy of the value at "from" at "path".
    test:    the target must exist and equal "value". Equality is JSON equality: numbers by value (1 == 1.0),
             booleans are never equal to numbers, objects by keys and values, lists elementwise.
    """
    import copy

    def parse_pointer(path, allow_dash=False):
        if not isinstance(path, str):
            raise PatchError

        if path == "":
            return []

        if path[0] != "/":
            raise PatchError

        raw_tokens = path[1:].split("/")
        tokens = []

        for raw in raw_tokens:
            token = []
            i = 0
            while i < len(raw):
                ch = raw[i]
                if ch == "~":
                    if i + 1 >= len(raw):
                        raise PatchError
                    nxt = raw[i + 1]
                    if nxt == "0":
                        token.append("~")
                    elif nxt == "1":
                        token.append("/")
                    else:
                        raise PatchError
                    i += 2
                else:
                    token.append(ch)
                    i += 1

            tokens.append("".join(token))

        if not allow_dash and "-" in tokens:
            raise PatchError

        return tokens

    def is_list_index(token):
        if token == "":
            return False
        if not all(c in "0123456789" for c in token):
            return False
        if len(token) > 1 and token[0] == "0":
            return False
        return True

    def get_value(root, tokens):
        cur = root
        for token in tokens:
            if isinstance(cur, dict):
                if token not in cur:
                    raise PatchError
                cur = cur[token]
            elif isinstance(cur, list):
                if not is_list_index(token):
                    raise PatchError
                idx = int(token)
                if idx >= len(cur):
                    raise PatchError
                cur = cur[idx]
            else:
                raise PatchError
        return cur

    def add_at(root, tokens, value, allow_dash=True):
        if not tokens:
            return copy.deepcopy(value)

        parent = get_value(root, tokens[:-1])
        token = tokens[-1]

        if isinstance(parent, dict):
            parent[token] = copy.deepcopy(value)
            return root

        if isinstance(parent, list):
            if token == "-":
                if not allow_dash:
                    raise PatchError
                parent.append(copy.deepcopy(value))
                return root

            if not is_list_index(token):
                raise PatchError

            idx = int(token)
            if idx > len(parent):
                raise PatchError

            parent.insert(idx, copy.deepcopy(value))
            return root

        raise PatchError

    def remove_at(root, tokens):
        if not tokens:
            raise PatchError

        parent = get_value(root, tokens[:-1])
        token = tokens[-1]

        if isinstance(parent, dict):
            if token not in parent:
                raise PatchError
            del parent[token]
            return root

        if isinstance(parent, list):
            if not is_list_index(token):
                raise PatchError
            idx = int(token)
            if idx >= len(parent):
                raise PatchError
            parent.pop(idx)
            return root

        raise PatchError

    def replace_at(root, tokens, value):
        if not tokens:
            return copy.deepcopy(value)

        parent = get_value(root, tokens[:-1])
        token = tokens[-1]

        if isinstance(parent, dict):
            if token not in parent:
                raise PatchError
            parent[token] = copy.deepcopy(value)
            return root

        if isinstance(parent, list):
            if not is_list_index(token):
                raise PatchError
            idx = int(token)
            if idx >= len(parent):
                raise PatchError
            parent[idx] = copy.deepcopy(value)
            return root

        raise PatchError

    def test_at(root, tokens, value):
        target = get_value(root, tokens)
        if not json_equal(target, value):
            raise PatchError
        return root

    def json_equal(a, b):
        if isinstance(a, bool) or isinstance(b, bool):
            if isinstance(a, bool) and isinstance(b, bool):
                return a == b
            return False

        if isinstance(a, (int, float)) and isinstance(b, (int, float)):
            return a == b

        if isinstance(a, dict) and isinstance(b, dict):
            if a.keys() != b.keys():
                return False
            return all(json_equal(a[k], b[k]) for k in a)

        if isinstance(a, list) and isinstance(b, list):
            if len(a) != len(b):
                return False
            return all(json_equal(x, y) for x, y in zip(a, b))

        return a == b

    def proper_descendant(source_tokens, target_tokens):
        if len(target_tokens) <= len(source_tokens):
            return False
        return target_tokens[:len(source_tokens)] == source_tokens

    work = copy.deepcopy(doc)

    for op in ops:
        if not isinstance(op, dict):
            raise PatchError

        op_name = op.get("op")
        if op_name not in {"add", "remove", "replace", "move", "copy", "test"}:
            raise PatchError

        if "path" not in op:
            raise PatchError

        path = op["path"]

        if op_name in {"add", "replace", "test"}:
            if "value" not in op:
                raise PatchError
            value = op["value"]

            if op_name == "add":
                tokens = parse_pointer(path, allow_dash=True)
                work = add_at(work, tokens, value, allow_dash=True)
            elif op_name == "replace":
                tokens = parse_pointer(path, allow_dash=False)
                work = replace_at(work, tokens, value)
            else:
                tokens = parse_pointer(path, allow_dash=False)
                work = test_at(work, tokens, value)

        elif op_name == "remove":
            tokens = parse_pointer(path, allow_dash=False)
            work = remove_at(work, tokens)

        elif op_name in {"move", "copy"}:
            if "from" not in op:
                raise PatchError

            from_path = op["from"]
            source_tokens = parse_pointer(from_path, allow_dash=False)
            target_tokens = parse_pointer(path, allow_dash=True)

            if op_name == "move":
                if proper_descendant(source_tokens, target_tokens):
                    raise PatchError

                if source_tokens == target_tokens:
                    get_value(work, source_tokens)
                    continue

                value = copy.deepcopy(get_value(work, source_tokens))
                work = remove_at(work, source_tokens)
                work = add_at(work, target_tokens, value, allow_dash=True)

            else:
                value = copy.deepcopy(get_value(work, source_tokens))
                work = add_at(work, target_tokens, value, allow_dash=True)

    return work

