def glob_match(pattern, path):
    """Return True if the "/"-separated relative `path` matches `pattern` (case-sensitive, whole path).

    Pattern syntax:
    - `?` matches exactly one character other than "/".
    - `*` matches zero or more characters other than "/".
    - `[...]` matches one character other than "/" that is in the set; `[!...]` one that is NOT in the set.
      The set holds literal characters and ranges `a-z`. A `]` right after `[` or `[!` is a literal member, and a
      `-` first or last in the set is literal. Backslash has no special meaning inside a set.
      An unterminated `[` raises ValueError.
    - `\\x` (backslash then any character) matches x literally. A trailing lone backslash raises ValueError.
    - A pattern segment (text between unescaped "/" outside sets) that is exactly `**` matches zero or more whole
      path segments. Elsewhere `**` is just two `*`.
    - Any other character matches itself.
    Matching must stay fast for patterns with many `*` or `**` (no exponential backtracking).
    """
    pattern_segments = _parse_pattern_segments(pattern)
    path_segments = path.split("/")

    def match_segments(pi, si):
        if pi == len(pattern_segments):
            return si == len(path_segments)

        seg = pattern_segments[pi]

        if seg == "**":
            # Match zero or more whole path segments.
            for next_si in range(si, len(path_segments) + 1):
                if match_segments(pi + 1, next_si):
                    return True
            return False

        if si == len(path_segments):
            return False

        return _match_segment(seg, path_segments[si]) and match_segments(pi + 1, si + 1)

    return match_segments(0, 0)


def _parse_pattern_segments(pattern):
    segments = []
    current = []
    i = 0
    n = len(pattern)

    while i < n:
        ch = pattern[i]

        if ch == "\\":
            if i + 1 >= n:
                raise ValueError("trailing lone backslash")
            nxt = pattern[i + 1]
            current.append(("lit", nxt))
            i += 2
            continue

        if ch == "/":
            segments.append(_segment_repr(current))
            current = []
            i += 1
            continue

        if ch == "?":
            current.append(("any",))
            i += 1
            continue

        if ch == "*":
            current.append(("star",))
            i += 1
            continue

        if ch == "[":
            current.append(_parse_char_class(pattern, i))
            i = _char_class_end(pattern, i)
            continue

        current.append(("lit", ch))
        i += 1

    segments.append(_segment_repr(current))
    return segments


def _segment_repr(tokens):
    if len(tokens) == 2 and tokens[0] == ("star",) and tokens[1] == ("star",):
        return "**"
    return tokens


def _parse_char_class(pattern, start):
    i = start + 1
    n = len(pattern)
    negated = False

    if i < n and pattern[i] == "!":
        negated = True
        i += 1

    members = []
    ranges = []
    first = True

    while i < n:
        ch = pattern[i]

        if ch == "]" and not first:
            return ("class", negated, members, ranges)

        first = False

        if i + 2 < n and pattern[i + 1] == "-" and pattern[i + 2] != "]":
            lo = ch
            hi = pattern[i + 2]
            if lo <= hi:
                ranges.append((lo, hi))
            else:
                members.append(lo)
                members.append(hi)
            i += 3
            continue

        members.append(ch)
        i += 1

    raise ValueError("unterminated [")


def _char_class_end(pattern, start):
    i = start + 1
    n = len(pattern)

    if i < n and pattern[i] == "!":
        i += 1

    if i < n and pattern[i] == "]":
        i += 1

    while i < n:
        if pattern[i] == "]":
            return i + 1
        i += 1

    raise ValueError("unterminated [")


def _match_segment(tokens, segment):
    if tokens == "**":
        return True

    m = len(tokens)
    n = len(segment)

    dp = [False] * (n + 1)
    dp[0] = True

    for token in tokens:
        ndp = [False] * (n + 1)

        if token[0] == "star":
            # star matches zero or more characters in this segment
            for j in range(n + 1):
                if dp[j]:
                    ndp[j] = True
                    for k in range(j + 1, n + 1):
                        ndp[k] = True
        else:
            for j in range(n):
                if dp[j] and _match_one(token, segment[j]):
                    ndp[j + 1] = True

        dp = ndp

    return dp[n]


def _match_one(token, ch):
    if ch == "/":
        return False

    kind = token[0]

    if kind == "lit":
        return token[1] == ch

    if kind == "any":
        return True

    if kind == "class":
        _, negated, members, ranges = token
        in_set = ch in members
        if not in_set:
            for lo, hi in ranges:
                if lo <= ch <= hi:
                    in_set = True
                    break
        return in_set if not negated else not in_set

    return False

