from datetime import datetime, timedelta


def next_fire(expr, after):
    """Return the first naive datetime STRICTLY after `after` (a naive datetime) that matches cron expression `expr`.
    Results always have second == 0 and microsecond == 0.

    `expr` has exactly 5 whitespace-separated fields: minute (0-59), hour (0-23), day-of-month (1-31),
    month (1-12), day-of-week (0-7, where both 0 and 7 mean Sunday, 1 = Monday ... 6 = Saturday).
    Each field is a comma-separated list of items. An item is "*" (the whole field range), "N", or "A-B" (A <= B),
    optionally followed by "/S" (S >= 1): take every S-th value of the item starting at its first value.
    "*/S" starts at the field minimum and "N/S" means N through the field maximum in steps of S.

    Day matching: a field is "unrestricted" only if it is exactly "*". If both day-of-month and day-of-week are
    restricted, a day matches when EITHER matches; otherwise both must match.

    Empty items, out-of-range values, A > B, S < 1, non-digit characters, or a wrong number of fields raise
    ValueError. If the expression has no match within 3000 days after `after` (e.g. "0 0 30 2 *"), raise ValueError.
    """
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError

    def _is_number(s):
        return s != "" and all("0" <= c <= "9" for c in s)

    def parse_field(field, lo, hi):
        if field == "":
            raise ValueError

        unrestricted = field == "*"
        values = set()

        for item in field.split(","):
            if item == "":
                raise ValueError

            if item.count("/") > 1:
                raise ValueError

            if "/" in item:
                base, step_s = item.split("/", 1)
                if not _is_number(step_s):
                    raise ValueError
                step = int(step_s)
                if step < 1:
                    raise ValueError
                has_step = True
            else:
                base = item
                step = 1
                has_step = False

            if base == "*":
                start, end = lo, hi
            elif "-" in base:
                if base.count("-") != 1:
                    raise ValueError
                a_s, b_s = base.split("-", 1)
                if not _is_number(a_s) or not _is_number(b_s):
                    raise ValueError
                a, b = int(a_s), int(b_s)
                if a < lo or b > hi or a > b:
                    raise ValueError
                start, end = a, b
            else:
                if not _is_number(base):
                    raise ValueError
                n = int(base)
                if n < lo or n > hi:
                    raise ValueError
                start = n
                end = hi if has_step else n

            values.update(range(start, end + 1, step))

        return values, unrestricted

    minute_set, _ = parse_field(fields[0], 0, 59)
    hour_set, _ = parse_field(fields[1], 0, 23)
    dom_set, dom_restricted = parse_field(fields[2], 1, 31)
    month_set, _ = parse_field(fields[3], 1, 12)
    dow_set, dow_restricted = parse_field(fields[4], 0, 7)

    dow_set = {0 if v == 7 else v for v in dow_set}

    minutes = sorted(minute_set)
    hours = sorted(hour_set)

    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = after + timedelta(days=3000)

    day = start.replace(hour=0, minute=0, second=0, microsecond=0)
    end_day = limit.replace(hour=0, minute=0, second=0, microsecond=0)

    while day <= end_day:
        cron_dow = (day.weekday() + 1) % 7

        if day.month in month_set:
            if dom_restricted and dow_restricted:
                day_ok = (day.day in dom_set) or (cron_dow in dow_set)
            else:
                day_ok = (day.day in dom_set) and (cron_dow in dow_set)

            if day_ok:
                for h in hours:
                    for m in minutes:
                        cand = day + timedelta(hours=h, minutes=m)
                        if cand < start:
                            continue
                        if cand > limit:
                            raise ValueError
                        return cand

        day += timedelta(days=1)

    raise ValueError

