import copy


class PatchError(ValueError):
    pass


def apply_patch(doc, ops):
    """Apply a JSON Patch (RFC 6902 subset) to `doc` and return the resulting NEW document.

    `doc` and `ops` must never be modified, and the result must share no mutable object (dict/list) with either.
    The patch is all-or-nothing: on any error, raise PatchError.

    `ops` is a list of dicts. Each has "op" (one of add, remove, replace, move, copy, test) and "path";
    add/replace/test also need "value" (which may be None); move/copy also need "from". Missing keys are errors.

    Paths are JSON Pointers: "" is the whole document; otherwise "/" followed by "/"-separated tokens in which
    "~1" stands for "/" and "~0" for "~" ("~01" is the key "~1"). A "~" not followed by 0 or 1 is an error.
    A token addressing a list must be a base-10 index without leading zeros ("0" is fine). "-" means "past the
    end of the list" and is only allowed as the final token of an add (or of the target of move/copy).

    add:     object -> set the member (replacing any existing value); list -> insert BEFORE the index
             (index == len appends, index > len is an error). Adding at "" replaces the whole document.
             The parent container must exist.
    remove:  the target must exist. Removing "" is an error.
    replace: the target must exist. Replacing "" replaces the whole document.
    move:    remove the value at "from", then add it at "path". It is an error if "path" lies strictly inside
             "from" (a proper descendant). from == path is a no-op, but "from" must still exist.
    copy:    add a deep copy of the value at "from" at "path".
    test:    the target must exist and equal "value". Equality is JSON equality: numbers by value (1 == 1.0),
             booleans are never equal to numbers, objects by keys and values, lists elementwise.
    """
    try:
        if not isinstance(ops, list):
            raise PatchError

        result = copy.deepcopy(doc)

        for op in ops:
            if not isinstance(op, dict):
                raise PatchError

            kind = op.get("op")
            if kind not in {"add", "remove", "replace", "move", "copy", "test"}:
                raise PatchError

            if "path" not in op:
                raise PatchError
            path = op["path"]
            if not isinstance(path, str):
                raise PatchError

            tokens = parse_pointer(path)

            if kind == "add":
                if "value" not in op:
                    raise PatchError
                value = copy.deepcopy(op["value"])
                result = add_at(result, tokens, value)

            elif kind == "remove":
                remove_at(result, tokens)

            elif kind == "replace":
                if "value" not in op:
                    raise PatchError
                value = copy.deepcopy(op["value"])
                result = replace_at(result, tokens, value)

            elif kind == "test":
                if "value" not in op:
                    raise PatchError
                if not json_equal(get_at(result, tokens), op["value"]):
                    raise PatchError

            elif kind == "move":
                if "from" not in op:
                    raise PatchError
                from_path = op["from"]
                if not isinstance(from_path, str):
                    raise PatchError

                from_tokens = parse_pointer(from_path)

                if is_proper_descendant(from_tokens, tokens):
                    raise PatchError

                if from_tokens == tokens:
                    get_at(result, from_tokens)
                    continue

                value = remove_at(result, from_tokens)
                result = add_at(result, tokens, value)

            elif kind == "copy":
                if "from" not in op:
                    raise PatchError
                from_path = op["from"]
                if not isinstance(from_path, str):
                    raise PatchError

                from_tokens = parse_pointer(from_path)
                value = copy.deepcopy(get_at(result, from_tokens))
                result = add_at(result, tokens, value)

        return result

    except Exception:
        raise PatchError


def parse_pointer(path):
    if path == "":
        return []

    if not path.startswith("/"):
        raise PatchError

    raw_tokens = path[1:].split("/")
    return [unescape_token(raw) for raw in raw_tokens]


def unescape_token(raw):
    out = []
    i = 0
    while i < len(raw):
        c = raw[i]
        if c == "~":
            if i + 1 >= len(raw):
                raise PatchError
            nxt = raw[i + 1]
            if nxt == "0":
                out.append("~")
            elif nxt == "1":
                out.append("/")
            else:
                raise PatchError
            i += 2
        else:
            out.append(c)
            i += 1
    return "".join(out)


def is_container(obj):
    return isinstance(obj, dict) or isinstance(obj, list)


def get_at(root, tokens):
    if not tokens:
        return root

    current = root
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                raise PatchError
            current = current[token]
        elif isinstance(current, list):
            idx = parse_list_index(token)
            if idx is None or idx >= len(current):
                raise PatchError
            current = current[idx]
        else:
            raise PatchError

    return current


def remove_at(root, tokens):
    if not tokens:
        raise PatchError

    parent = get_parent(root, tokens)

    token = tokens[-1]

    if isinstance(parent, dict):
        if token not in parent:
            raise PatchError
        return parent.pop(token)

    if isinstance(parent, list):
        idx = parse_list_index(token)
        if idx is None or idx >= len(parent):
            raise PatchError
        return parent.pop(idx)

    raise PatchError


def add_at(root, tokens, value):
    if not tokens:
        return value

    parent = get_parent(root, tokens)
    token = tokens[-1]

    if isinstance(parent, dict):
        parent[token] = value
        return root

    if isinstance(parent, list):
        if token == "-":
            parent.append(value)
            return root

        idx = parse_list_index(token)
        if idx is None or idx > len(parent):
            raise PatchError

        parent.insert(idx, value)
        return root

    raise PatchError


def replace_at(root, tokens, value):
    if not tokens:
        return value

    parent = get_parent(root, tokens)
    token = tokens[-1]

    if isinstance(parent, dict):
        if token not in parent:
            raise PatchError
        parent[token] = value
        return root

    if isinstance(parent, list):
        idx = parse_list_index(token)
        if idx is None or idx >= len(parent):
            raise PatchError
        parent[idx] = value
        return root

    raise PatchError


def get_parent(root, tokens):
    current = root
    for token in tokens[:-1]:
        if isinstance(current, dict):
            if token not in current:
                raise PatchError
            current = current[token]
        elif isinstance(current, list):
            idx = parse_list_index(token)
            if idx is None or idx >= len(current):
                raise PatchError
            current = current[idx]
        else:
            raise PatchError
    return current


def parse_list_index(token):
    if token == "-":
        return None

    if not token:
        return None

    if token[0] == "-":
        return None

    if not token.isdigit():
        return None

    if len(token) > 1 and token[0] == "0":
        return None

    return int(token)


def is_proper_descendant(from_tokens, path_tokens):
    if len(path_tokens) <= len(from_tokens):
        return False
    return from_tokens == path_tokens[:len(from_tokens)]


def json_equal(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b

    if isinstance(a, dict) and isinstance(b, dict):
        if a.keys() != b.keys():
            return False
        return all(json_equal(a[k], b[k]) for k in a)

    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return False
        return all(json_equal(x, y) for x, y in zip(a, b))

    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b

    return a == b

